INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das BDSG eine eigenständige Datenschutzregelung?', 2, '[{"text": "Nein", "correct": true, "because": "Es ergänzt die DSGVO"}, {"text": "Ja", "correct": false, "because": "Abhängig von der DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das BDSG?', 3, '[{"text": "Nationale Anpassung der DSGVO", "correct": true, "because": "Regelt deutsche Besonderheiten"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Nicht primär"}, {"text": "Technische Optimierung", "correct": false, "because": "Kein Datenschutzfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche regelt das BDSG zusätzlich zur DSGVO?', 5, '[{"text": "Beschäftigtendatenschutz", "correct": true, "because": "Regelt Arbeitnehmerdaten"}, {"text": "Öffentliche Stellen", "correct": true, "because": "Spezifiziert Behörden"}, {"text": "Farbgestaltung", "correct": false, "because": "Nicht datenschutzrelevant"}, {"text": "Serverleistung", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BDSG ergänzt die DSGVO. b) Es ersetzt die DSGVO in Deutschland.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DSGVO bleibt maßgeblich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Anwendung des BDSG?', 4, '[{"text": "Spezifische nationale Regeln", "correct": false, "because": "Kern des BDSG"}, {"text": "Datenschutzbeauftragte", "correct": false, "because": "Pflicht geregelt"}, {"text": "UI-Design", "correct": true, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das BDSG auch für den öffentlichen Sektor gilt?', 2, '[{"text": "Ja", "correct": true, "because": "Regelt Behörden spezifisch"}, {"text": "Nein", "correct": false, "because": "Umfasst öffentliche Stellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das BDSG für Beschäftigtendaten?', 3, '[{"text": "Regelt Verarbeitung", "correct": true, "because": "Schützt Arbeitnehmerdaten"}, {"text": "Ignoriert diese", "correct": false, "because": "Spezifischer Fokus"}, {"text": "Verbietet Verarbeitung", "correct": false, "because": "Regelt, nicht verbietet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt das BDSG an Unternehmen?', 5, '[{"text": "Datenschutzbeauftragten ernennen", "correct": true, "because": "Pflicht bei Risiko"}, {"text": "Videoüberwachung regeln", "correct": true, "because": "Spezifische Vorgaben"}, {"text": "Maximale Datensammlung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das BDSG spezifiziert DSGVO-Regeln. b) Es gilt nur für private Unternehmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch öffentliche Stellen betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Einhaltung des BDSG?', 4, '[{"text": "Dokumentation der Verarbeitung", "correct": false, "because": "Nachweispflicht"}, {"text": "Spezifische Beschäftigtenregeln", "correct": false, "because": "BDSG-Fokus"}, {"text": "Grafische Gestaltung", "correct": true, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt das BDSG die DSGVO?', 2, '[{"text": "Nein", "correct": true, "because": "Es ergänzt sie nur"}, {"text": "Ja", "correct": false, "because": "DSGVO bleibt Basis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche deckt das BDSG ab?', 4, '[{"text": "Scoring und Profiling", "correct": true, "because": "Regelt spezifische Nutzung"}, {"text": "Öffentliche Stellen", "correct": true, "because": "Spezifische Vorgaben"}, {"text": "Serverstandorte", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das BDSG nur für Arbeitnehmer gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst auch andere Bereiche"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Umsetzung des BDSG?', 3, '[{"text": "Beschäftigtendatenschutz", "correct": true, "because": "Spezifischer Fokus"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Irrelevant"}, {"text": "Maximale Speicherung", "correct": false, "because": "Widerspricht DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BDSG regelt Videoüberwachung. b) Es hebt die DSGVO auf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DSGVO bleibt gültig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten ergänzt das BDSG zur DSGVO?', 5, '[{"text": "Datenschutzbeauftragter", "correct": true, "because": "Spezifische Ernennung"}, {"text": "Verbraucherdatenschutz", "correct": true, "because": "Regelt Scoring"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Einhaltung des BDSG unwichtig?', 3, '[{"text": "Beschäftigtenregeln", "correct": false, "because": "Kern des BDSG"}, {"text": "Dokumentation", "correct": false, "because": "Nachweispflicht"}, {"text": "Animationseffekte", "correct": true, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit dem BDSG? Gilt es nur für Behörden?', 3, '[{"text": "Nein", "correct": true, "because": "Auch private Unternehmen betroffen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das BDSG eigene Strafen vorsieht?', 2, '[{"text": "Ja", "correct": true, "because": "Bußgelder sind möglich"}, {"text": "Nein", "correct": false, "because": "Ergänzt DSGVO-Sanktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für die BDSG-Umsetzung?', 4, '[{"text": "Beschäftigtendatenschutz", "correct": true, "because": "Spezifische Regelung"}, {"text": "Zufällige Datensammlung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Schutzfokus"}]');
